<template>
  <section class="run-report" data-drift-report aria-label="Souvenirs de l’expédition">
    <header class="report-cover">
      <div class="cover-seal"><drift-glyph name="trophy" /></div>
      <div class="cover-copy"><span class="eyebrow">LE CARNET DES SURVIVANTS</span><h3>{{ winner ? `${winner.username} remporte l’expédition` : 'Chacun a laissé sa trace' }}</h3><p>{{ players.length }} dresseurs · {{ duration(report.durationMs) }} de voyage<span v-if="report.rules?.durationMinutes"> · exploration prévue : {{ report.rules.durationMinutes }} min</span></p></div>
      <button class="export-button" data-report-export @click="downloadReport"><drift-glyph name="progress" />Garder le carnet <small>Fichier JSON</small></button>
    </header>
    <p class="report-note">Les équipes, les Balls et le butin jouables ont été effacés à la fin de cette expédition. Leurs souvenirs restent dans ce carnet : retrouve le parcours de chaque dresseur.</p>

    <section v-if="accountReward" class="report-account-reward" data-report-account-reward data-rift-reward-detail aria-label="Calcul de la prime du vainqueur">
      <div class="prize-heading"><span class="prize-seal" aria-hidden="true"><drift-glyph name="coin" /></span><div><span class="eyebrow">PRIME DU VAINQUEUR</span><strong>{{ number(accountReward.coinsAwarded) }} <small>pièces RiftMon</small></strong></div></div>
      <dl class="prize-factors"><div><dt>Dresseurs au départ</dt><dd>{{ number(accountReward.participantCount) }}</dd></div><div><dt>Exploration jouée</dt><dd>{{ rewardDuration(accountReward.explorationMs) }}</dd></div><div><dt>Par dresseur et minute</dt><dd>{{ number(accountReward.coinsPerPlayerMinute) }} pièces</dd></div></dl>
      <p>{{ winner ? `Prime calculée pour ${winner.username}, arrondie à la pièce inférieure.` : 'Aucun vainqueur : aucune pièce attribuée.' }} Le temps du tournoi est exclu.</p>
      <small v-if="winner" class="prize-account-note">Montant prévu pour le compte du vainqueur. Consulte ton solde au camp pour retrouver les pièces créditées.</small>
    </section>

    <div v-if="highlights.length" class="highlights" aria-label="Les faits marquants">
      <article v-for="highlight in highlights" :key="highlight.key"><drift-glyph :name="highlight.icon" /><div><span>{{ highlight.title }}</span><strong :title="highlight.names">{{ highlight.name }}</strong><small>{{ number(highlight.value) }} {{ highlight.unit }}</small></div></article>
    </div>

    <div class="chapter-title"><span>01</span><h4>Les dresseurs & leurs équipes</h4></div>
    <p class="hint">Choisis un dresseur pour feuilleter son aventure.</p>
    <div class="player-collection" aria-label="Dresseurs de l’expédition">
      <button v-for="player in players" :key="player.id" :data-report-player="player.id" class="player-card" :class="{ selected: selected?.id === player.id, champion: player.id === report.winnerId }" :aria-pressed="selected?.id === player.id" @click="selectPlayer(player.id)">
        <span class="player-heading"><span><strong>{{ player.username }}</strong><small v-if="player.id === Number(userId)">TOI</small></span><drift-glyph v-if="player.id === report.winnerId" name="trophy" /></span>
        <span class="roster-mini"><pokemon-portrait v-for="pokemon in (player.team || []).slice(0, 6)" :key="pokemon.uuid" :src="portrait(pokemon)" :alt="pokemon.name" /><span v-if="!(player.team || []).length" class="hint">Équipe non disponible</span></span>
        <span class="player-caption">{{ resultLabel(player) }}<span>{{ duration(player.survivedMs) }}</span></span>
      </button>
    </div>

    <article v-if="selected" class="player-story" :aria-label="`Le parcours de ${selected.username}`">
      <header class="story-heading"><div><span class="eyebrow">LE VOYAGE DE</span><h4>{{ selected.username }}</h4></div><span class="result-stamp" :class="{ champion: selected.id === report.winnerId }">{{ resultLabel(selected) }}</span></header>
      <div class="key-figures"><div><strong>{{ number(stat('battles')) }}</strong><span>combats</span></div><div><strong>{{ number(stat('captures')) }}</strong><span>captures</span></div><div><strong>{{ number(stat('driftsFound')) }}</strong><span>Drifts trouvés</span></div><div><strong>{{ number(stat('xpGained')) }}</strong><span>XP gagnée</span></div></div>

      <div v-if="selected.starter" class="starter-memory"><pokemon-portrait :src="portrait(selected.starter)" :alt="selected.starter.name" /><div><span>Tout a commencé avec</span><strong>{{ selected.starter.name }} <small>niveau {{ selected.starter.level }}</small></strong></div><potential-star :value="selected.starter.potential || 1" /></div>
      <div class="team-caption"><h5>{{ teamView === 'tournament' ? 'L’équipe à l’entrée du tournoi' : 'La dernière équipe' }}</h5><div v-if="selected.tournamentTeam?.length" class="team-switch" aria-label="Moment de l’équipe"><button data-report-team-view="final" :aria-pressed="teamView === 'final'" @click="teamView = 'final'">Fin du parcours</button><button data-report-team-view="tournament" :aria-pressed="teamView === 'tournament'" @click="teamView = 'tournament'">Entrée au tournoi</button></div></div>
      <p class="hint team-hint">{{ teamView === 'tournament' ? 'Le groupe réuni avant le premier round.' : 'La dernière équipe conservée pour ce dresseur. Les compagnons perdus en chemin restent dans le carnet.' }} Ouvre une fiche pour voir ses capacités et son potentiel.</p>
      <div class="report-team" data-report-team>
        <details v-for="pokemon in visibleTeam" :key="`${teamView}-${selected.id}-${pokemon.uuid}`" class="pokemon-card" :class="{ fallen: pokemon.lostAt != null }">
          <summary><span class="pokemon-art"><pokemon-portrait :src="portrait(pokemon)" :alt="pokemon.name" /></span><span class="pokemon-copy"><span class="pokemon-name">{{ pokemon.name }}<potential-star :value="pokemon.potential || 1" /></span><span class="pokemon-level">N. {{ pokemon.level }}<small v-if="pokemon.initialLevel && pokemon.level > pokemon.initialLevel"> +{{ pokemon.level - pokemon.initialLevel }} niveaux</small></span><span class="pokemon-status">{{ pokemon.lostAt != null ? `Tombé à ${elapsed(pokemon.lostAt)}` : 'Dernier état conservé' }}</span></span><span class="expand-mark" aria-hidden="true">+</span></summary>
          <div class="pokemon-details"><p class="pokemon-traits"><span>{{ (pokemon.types || []).map(typeLabel).join(' / ') }}</span><span v-if="pokemon.nature">Nature {{ natureLabel(pokemon.nature) }}</span><span v-if="pokemon.passiveAbility">Talent : {{ abilityLabel(pokemon.passiveAbility) }}</span></p><p class="hint">{{ pokemon.source === 'starter' ? 'Compagnon de départ' : pokemon.source === 'capture' ? 'Capturé' : 'Compagnon' }}<span v-if="pokemon.obtainedAt"> · {{ elapsed(pokemon.obtainedAt) }}</span></p><table class="pokemon-stats"><caption>Statistiques, potentiel IV et entraînement EV</caption><thead><tr><th scope="col">Stat</th><th scope="col">Valeur</th><th scope="col">IV</th><th scope="col">EV</th></tr></thead><tbody><tr v-for="attribute in attributes" :key="attribute.key"><th scope="row">{{ attribute.label }}</th><td>{{ numberOrDash(pokemon.stats?.[attribute.key]) }}</td><td>{{ numberOrDash(pokemon.ivs?.[attribute.key]) }}</td><td>{{ numberOrDash(pokemon.evs?.[attribute.key]) }}</td></tr></tbody></table><div v-if="pokemon.moves?.length" class="move-list"><span v-for="(move,index) in (pokemon.moveNames || pokemon.moves)" :key="index">{{ moveLabel(move) }}</span></div></div>
        </details>
        <p v-if="!visibleTeam.length" class="hint">Aucune équipe conservée pour ce dresseur.</p>
      </div>

      <div class="chapter-title"><span>02</span><h4>Sa combinaison de Drifts</h4></div>
      <p class="hint">Les cinq emplacements tels qu’ils étaient à la fin de son parcours.</p>
      <div class="report-loadout"><details v-for="(drift,index) in equippedSlots" :key="`${selected.id}-${index}`" class="report-drift" :class="{ empty: !drift }"><summary><span class="drift-slot">0{{ index + 1 }}</span><drift-glyph :category="drift?.category" :rarity="drift?.rarity" /><strong>{{ drift?.name || 'Libre' }}</strong><small v-if="drift">{{ rarityLabel(drift.rarity) }}</small></summary><p v-if="drift">{{ drift.description }}<span v-if="drift.element"> · Type {{ typeLabel(drift.element) }}</span><span v-if="drift.value != null"> · Valeur : {{ drift.value }} {{ drift.unit }}</span></p><p v-else>Aucun Drift dans cet emplacement.</p></details></div>

      <details class="story-fold" data-report-statistics><summary><span><drift-glyph name="progress" />Tous les chiffres du voyage</span><span class="expand-mark" aria-hidden="true">+</span></summary><div class="statistics-groups"><section v-for="group in statisticGroups" :key="group.title"><h5>{{ group.title }}</h5><dl><div v-for="item in group.items" :key="item.key"><dt>{{ item.label }}</dt><dd>{{ number(stat(item.key)) }}{{ item.suffix || '' }}</dd></div></dl></section></div></details>

      <details class="story-fold" data-report-companions><summary><span><drift-glyph name="team" />Tous ses compagnons <small>{{ allPokemon.length }}</small></span><span class="expand-mark" aria-hidden="true">+</span></summary><p class="hint fold-hint">Du tout premier partenaire aux Pokémon perdus en chemin.</p><div class="companions-list"><article v-for="pokemon in allPokemon" :key="pokemon.uuid"><pokemon-portrait :src="portrait(pokemon)" :alt="pokemon.name" /><div><strong>{{ pokemon.name }} <small>N. {{ pokemon.level }}</small></strong><span>{{ pokemon.source === 'starter' ? 'Compagnon de départ' : 'Rencontré en chemin' }} · {{ elapsed(pokemon.obtainedAt) }}</span><small :class="{ 'loss-text': pokemon.lostAt != null }">{{ pokemon.lostAt != null ? `Tombé à ${elapsed(pokemon.lostAt)}` : 'A survécu à son parcours' }}</small></div><potential-star :value="pokemon.potential || 1" /></article></div><p v-if="selected.pokemonOmitted" class="hint fold-hint">{{ number(selected.pokemonOmitted) }} compagnons supplémentaires ne sont pas détaillés. Les totaux sont conservés.</p></details>

      <details class="story-fold" data-report-loot><summary><span><drift-glyph name="drift" />Le butin de l’expédition <small>{{ (selected.drifts || []).length }}</small></span><span class="expand-mark" aria-hidden="true">+</span></summary><div class="loot-list"><article v-for="(drift,index) in selected.drifts || []" :key="drift.uuid || index"><drift-glyph :category="drift.category" :rarity="drift.rarity" /><div><strong>{{ drift.name }}</strong><small>{{ rarityLabel(drift.rarity) }}<span v-if="drift.element"> · {{ typeLabel(drift.element) }}</span></small></div><span>{{ driftStatus(drift.status) }}</span></article><p v-if="!selected.drifts?.length" class="hint">Aucun Drift trouvé pendant ce voyage.</p></div><p v-if="selected.driftsOmitted" class="hint fold-hint">{{ number(selected.driftsOmitted) }} Drifts supplémentaires ne sont pas détaillés. Les totaux sont conservés.</p><p v-if="selected.finalMoney != null" class="hint fold-hint">À la fin du parcours : {{ number(selected.finalMoney) }} ₽<span v-for="item in selected.finalItems || []" :key="item.key"> · {{ item.name }} ×{{ number(item.quantity) }}</span></p></details>

      <div class="chapter-title"><span>03</span><h4>Les traces de son aventure</h4></div>
      <div v-if="selected.visitedMaps?.length" class="visited-maps" aria-label="Lieux découverts"><span v-for="(place,index) in selected.visitedMaps" :key="`${place.map}-${index}`" :title="`Découvert à ${elapsed(place.visitedAt)}`"><small>{{ String(index + 1).padStart(2, '0') }}</small>{{ mapLabel(place.map) }}</span></div>
      <details class="story-fold journal-fold" data-report-journal><summary><span><drift-glyph name="compass" />Le journal de bord <small>{{ (selected.events || []).length }} souvenirs</small></span><span class="expand-mark" aria-hidden="true">+</span></summary><ol class="journey-events" data-report-events><li v-for="(event,index) in visibleEvents" :key="`${selected.id}-${index}`" :class="`event-${event.type}`"><time>{{ elapsed(event.at) }}</time><span>{{ eventText(event) }}</span></li></ol><p v-if="!selected.events?.length" class="hint fold-hint">Le journal de ce voyage est vide.</p><button v-if="eventLimit < (selected.events || []).length" class="more-events" data-report-more-events @click="eventLimit += 40">Lire la suite · {{ selected.events.length - eventLimit }} souvenirs</button><p v-if="selected.eventsOmitted" class="hint fold-hint">{{ number(selected.eventsOmitted) }} événements plus anciens ne figurent plus dans le journal. Les totaux du voyage sont conservés.</p></details>
    </article>
    <p v-if="downloadFeedback" class="download-feedback" role="status">{{ downloadFeedback }}</p>
  </section>
</template>

<script>
import DriftGlyph from './DriftGlyph.vue';
import PokemonPortrait from '../PokemonPortrait.vue';
import PotentialStar from '../PotentialStar.vue';
import { getMapLocationLabel } from '@/services/mapLocations';
import { localizeMoveName, localizeAbilityName } from '@/services/i18n';

const NATURES = { Hardy: 'Hardi', Lonely: 'Solo', Brave: 'Brave', Adamant: 'Rigide', Naughty: 'Mauvais', Bold: 'Assuré', Docile: 'Docile', Relaxed: 'Relax', Impish: 'Malin', Lax: 'Lâche', Timid: 'Timide', Hasty: 'Pressé', Serious: 'Sérieux', Jolly: 'Jovial', Naive: 'Naïf', Modest: 'Modeste', Mild: 'Doux', Quiet: 'Discret', Bashful: 'Pudique', Rash: 'Foufou', Calm: 'Calme', Gentle: 'Gentil', Sassy: 'Malpoli', Careful: 'Prudent', Quirky: 'Bizarre' };
const TYPES = { Normal: 'Normal', Fire: 'Feu', Water: 'Eau', Electric: 'Électrik', Grass: 'Plante', Ice: 'Glace', Fighting: 'Combat', Poison: 'Poison', Ground: 'Sol', Flying: 'Vol', Psychic: 'Psy', Bug: 'Insecte', Rock: 'Roche', Ghost: 'Spectre', Dragon: 'Dragon', Dark: 'Ténèbres', Steel: 'Acier', Fairy: 'Fée' };
const STATISTIC_GROUPS = [
  { title: 'Les rencontres', items: [{ key: 'battles', label: 'Combats disputés' }, { key: 'wildWins', label: 'Victoires sauvages' }, { key: 'trainerWins', label: 'Dresseurs vaincus' }, { key: 'arenaWins', label: 'Champions vaincus' }, { key: 'pvpWins', label: 'Duels remportés' }, { key: 'defeats', label: 'Défaites' }, { key: 'draws', label: 'Égalités' }, { key: 'interrupted', label: 'Combats interrompus' }, { key: 'fled', label: 'Fuites' }] },
  { title: 'Les compagnons', items: [{ key: 'captures', label: 'Captures réussies' }, { key: 'captureAttempts', label: 'Balls lancées' }, { key: 'pokemonLost', label: 'Pokémon tombés' }, { key: 'xpGained', label: 'XP gagnée' }, { key: 'levelsGained', label: 'Niveaux gagnés' }, { key: 'evolutions', label: 'Évolutions' }, { key: 'potionsUsed', label: 'Potions utilisées' }, { key: 'centerHeals', label: 'Soins au Centre' }] },
  { title: 'La récolte', items: [{ key: 'moneyEarned', label: 'Argent gagné', suffix: ' ₽' }, { key: 'moneySpent', label: 'Argent dépensé', suffix: ' ₽' }, { key: 'driftsFound', label: 'Drifts trouvés' }, { key: 'driftsSold', label: 'Drifts revendus' }, { key: 'driftsDiscarded', label: 'Drifts supprimés' }, { key: 'steps', label: 'Pas parcourus' }] }
];

export default {
  name: 'DriftRunReport',
  components: { DriftGlyph, PokemonPortrait, PotentialStar },
  props: { report: { type: Object, required: true }, userId: { type: [Number, String], default: null } },
  data() { return { selectedId: null, teamView: 'final', eventLimit: 40, downloadFeedback: '', statisticGroups: STATISTIC_GROUPS, attributes: [{ key: 'hp', label: 'PV' }, { key: 'attack', label: 'Attaque' }, { key: 'defense', label: 'Défense' }, { key: 'specialAttack', label: 'Atq. Spé.' }, { key: 'specialDefense', label: 'Déf. Spé.' }, { key: 'speed', label: 'Vitesse' }] }; },
  computed: {
    accountReward() {
      const reward = this.report.accountReward;
      return reward?.version === 1 && ['participantCount', 'explorationMs', 'coinsPerPlayerMinute', 'coinsAwarded'].every(key => Number.isFinite(reward[key]) && reward[key] >= 0) ? reward : null;
    },
    players() { return this.report.players || []; },
    winner() { return this.players.find(player => player.id === this.report.winnerId); },
    selected() { return this.players.find(player => player.id === this.selectedId) || this.players.find(player => player.id === Number(this.userId)) || this.winner || this.players[0]; },
    visibleTeam() { return this.selected?.[this.teamView === 'tournament' ? 'tournamentTeam' : 'team'] || []; },
    allPokemon() { return this.selected?.pokemon || []; },
    equippedSlots() { return Array.from({ length: 5 }, (_, index) => this.selected?.equippedDrifts?.[index] || null); },
    visibleEvents() { return (this.selected?.events || []).slice(0, this.eventLimit); },
    highlights() {
      return [{ key: 'captures', title: 'L’âme de collectionneur', icon: 'team', unit: 'captures' }, { key: 'pvpWins', title: 'Le goût du duel', icon: 'trophy', unit: 'victoires en duel' }, { key: 'xpGained', title: 'Une équipe qui grandit', icon: 'progress', unit: 'XP gagnée' }, { key: 'steps', title: 'L’appel du voyage', icon: 'compass', unit: 'pas parcourus' }].map(item => {
        const value = Math.max(0, ...this.players.map(player => Number(player.stats?.[item.key]) || 0));
        const leaders = this.players.filter(player => value > 0 && Number(player.stats?.[item.key]) === value).map(player => player.username);
        return { ...item, value, names: leaders.join(', '), name: leaders.length > 2 ? `${leaders.slice(0, 2).join(', ')} +${leaders.length - 2}` : leaders.join(' & ') };
      }).filter(item => item.value > 0);
    }
  },
  watch: { 'report.runId'() { this.selectedId = null; this.teamView = 'final'; this.eventLimit = 40; this.downloadFeedback = ''; } },
  methods: {
    rewardDuration(ms) { const seconds = Math.max(0, Math.floor((Number(ms) || 0) / 1000)); return `${Math.floor(seconds / 60)} min ${String(seconds % 60).padStart(2, '0')} s`; },
    selectPlayer(id) { this.selectedId = id; this.teamView = 'final'; this.eventLimit = 40; },
    number(value) { return (Number(value) || 0).toLocaleString('fr-FR'); },
    numberOrDash(value) { return value == null ? '—' : this.number(value); },
    stat(key) { return this.selected?.stats?.[key] || 0; },
    portrait(pokemon) { return `${process.env.BASE_URL}img/pokemon/front/${Number(pokemon.pokemonId) || 1}.png`; },
    typeLabel(value) { return TYPES[value] || value; },
    natureLabel(value) { return NATURES[value] || value; },
    moveLabel(move) { return localizeMoveName(typeof move === 'string' ? move : move.name || move.fname || move.ename || 'Capacité', 'fr'); },
    abilityLabel(ability) { return localizeAbilityName(ability, 'fr'); },
    mapLabel(map) { return getMapLocationLabel(map, 'fr'); },
    eventText(event) { return event.type === 'map' && event.map ? `Arrivée : ${this.mapLabel(event.map)}.` : event.text; },
    rarityLabel(key) { return { common: 'Commun', rare: 'Rare', epic: 'Épique', legendary: 'Légendaire', mythic: 'Mythique' }[key] || key; },
    driftStatus(status) { return { equipped: 'Équipé', owned: 'Dans le sac', stored: 'Dans le sac', collected: 'Dans le sac', sold: 'Vendu', discarded: 'Supprimé' }[status] || 'Trouvé'; },
    resultLabel(player) { if (player.id === this.report.winnerId) return 'Vainqueur'; return { disconnected: 'Forfait · déconnexion', forfeit: 'Abandon', defeated: 'Équipe tombée', not_ready: 'Forfait · non prêt', finished: 'Voyage terminé' }[player.reason] || 'Voyage terminé'; },
    duration(ms) { const seconds = Math.max(0, Math.floor((Number(ms) || 0) / 1000)); const minutes = Math.floor(seconds / 60); return minutes >= 60 ? `${Math.floor(minutes / 60)} h ${String(minutes % 60).padStart(2, '0')}` : `${minutes} min ${String(seconds % 60).padStart(2, '0')} s`; },
    elapsed(at) { const seconds = Math.max(0, Math.floor(((Number(at) || Number(this.report.startedAt)) - Number(this.report.startedAt)) / 1000)); const minutes = Math.floor(seconds / 60); return `${String(minutes).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`; },
    downloadReport() {
      let url;
      try {
        const blob = new Blob([JSON.stringify(this.report, null, 2)], { type: 'application/json;charset=utf-8' });
        url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url; link.download = `explorakit-drift-${String(this.report.runId || 'souvenirs').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 80)}.json`;
        document.body.appendChild(link); link.click(); link.remove();
        this.downloadFeedback = 'Ton carnet a été préparé pour le téléchargement.';
      } catch (error) { this.downloadFeedback = 'Le carnet n’a pas pu être téléchargé. Réessaie dans ton navigateur.'; }
      if (url) setTimeout(() => URL.revokeObjectURL(url), 1000);
    }
  }
};
</script>

<style scoped>
.run-report { --ink: #253f4c; --muted: #6c7b72; --gold: #ac8d50; color: var(--ink); font: 13px/1.5 'Trebuchet MS', Arial, sans-serif; text-align: left; min-width: 0; padding-bottom: 24px; }
.run-report *, .run-report *::before, .run-report *::after { box-sizing: border-box; }button { font: inherit; cursor: pointer; min-height: 44px; }button:focus-visible, summary:focus-visible { outline: 2px solid #a97d31; outline-offset: 3px; }.report-cover { position: relative; display: flex; align-items: center; gap: 17px; padding: 24px; border: 1px solid #c2a56b; border-radius: 11px; background: radial-gradient(ellipse at top right, #37565a, #142c3c 70%); color: #fff1d0; overflow: hidden; }.cover-seal { flex-shrink: 0; display: grid; place-items: center; width: 58px; height: 58px; border: 1px solid #c5a56865; border-radius: 50%; color: #e0c181; box-shadow: 0 0 0 5px #c5a5680b; }.cover-seal svg { width: 33px; height: 33px; }.cover-copy { flex: 1; min-width: 0; }.eyebrow { font-size: 9px; font-weight: bold; letter-spacing: .12em; }.cover-copy .eyebrow { color: #b6c6b8; }.cover-copy h3 { margin: 6px 0 8px; font: 500 28px/1.1 Georgia, serif; overflow-wrap: anywhere; }.cover-copy p { margin: 0; color: #b9c9c0; font-size: 10px; }.export-button { display: grid; grid-template-columns: 18px 1fr; gap: 0 7px; align-items: center; flex-shrink: 0; padding: 9px 11px; border: 1px solid #c4af7c88; border-radius: 6px; color: #efe2bf; background: #ffffff09; font-size: 10px; text-align: left; }.export-button svg { width: 18px; height: 18px; grid-row: span 2; }.export-button small { font-size: 8px; color: #bcc9bb; }.report-note { margin: 13px 0 20px; font-size: 11px; color: var(--muted); }.highlights { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin-bottom: 25px; }.highlights article { display: flex; align-items: flex-start; gap: 9px; min-width: 0; padding: 3px 0; }.highlights svg { width: 21px; height: 21px; color: #a78c54; margin-top: 2px; }.highlights article > div { min-width: 0; }.highlights span, .highlights strong, .highlights small { display: block; }.highlights span { font-size: 8px; text-transform: uppercase; letter-spacing: .04em; color: #748075; }.highlights strong { font-size: 11px; overflow-wrap: anywhere; }.highlights small { font-size: 10px; color: #567169; }
